// ─── File: MarkerDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.marker;

import java.io.ByteArrayOutputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MarkerDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        LoginSession session = new LoginSession("Rajesh", "token-xyz");

        ArchiveService archive = new ArchiveService();
        AuditService audit = new AuditService();

        // Serializable marker gate: Account passes, LoginSession is rejected.
        archive.tryArchive(rajesh);
        archive.tryArchive(session);

        // Custom Auditable marker gate: only Account is auditable.
        audit.recordIfAuditable(rajesh);
        audit.recordIfAuditable(session);
    }
}

// ─── Would be in Auditable.java (CUSTOM marker interface: no methods) ───
interface Auditable {
    // Intentionally empty. Presence of this type is the only signal.
}

// ─── Would be in Account.java (carries TWO marker interfaces) ───
class Account implements Serializable, Auditable {
    private static final long serialVersionUID = 1L;
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    BigDecimal getBalance() { return balance; }
    String getAccountId() { return accountId; }
}

// ─── Would be in LoginSession.java (NOT serializable, NOT auditable) ───
class LoginSession {
    private final String user;
    private final transient String token; // secret, must never be archived
        LoginSession(String user, String token) { this.user = user;
        this.token = token; }
    String getUser() { return user; }
}

// ─── Would be in ArchiveService.java (uses the Serializable marker) ───
class ArchiveService {
    private static final Logger log = Logger.getLogger("BankLog");
    void tryArchive(Object obj) {
        // The serialization machinery itself checks instanceof Serializable.
        if (!(obj instanceof Serializable)) {
            log.severe(() -> "REJECTED archive: " + obj.getClass().getSimpleName()
                    + " is not Serializable");
            return;
        }
        try (ByteArrayOutputStream bytes = new ByteArrayOutputStream();
             ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(obj);
            log.info(() -> "Archived " + obj.getClass().getSimpleName()
                    + " as " + bytes.size() + " bytes");
        } catch (Exception e) {
            log.log(Level.SEVERE, "Archive failed", e);
        }
    }
}

// ─── Would be in AuditService.java (uses our CUSTOM marker) ───
class AuditService {
    private static final Logger log = Logger.getLogger("BankLog");
    void recordIfAuditable(Object entity) {
        // Our own marker check: only tagged entities are written to audit trail.
        if (entity instanceof Auditable) {
            log.info(() -> "AUDIT recorded change for " + entity.getClass().getSimpleName());
        } else {
            log.fine(() -> "Skipped audit for " + entity.getClass().getSimpleName()
                    + " (not Auditable)");
        }
    }
}
